"use client";

import { ChangeEvent, useMemo, useState } from "react";
import { createClient } from "@/lib/supabase-browser";
import type { Project, ProjectImage } from "@/lib/projects";

type Row = Project & { images: ProjectImage[] };
const empty:any={id:"",title:"",slug:"",location:"",area:"",year:null,description:"",cover_image:null,hero_image:null,sketch_image:null,likes_count:0,position:999,featured:false,published:true,created_at:"",updated_at:"",images:[]};
function slugify(v:string){return v.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");}
function safe(v:string){return v.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^\w.-]+/g,"-");}

export default function AdminProjectManager({initialProjects}:{initialProjects:Row[]}){
  const [projects,setProjects]=useState(initialProjects); const [selectedId,setSelectedId]=useState(initialProjects[0]?.id||"new");
  const selected=useMemo(()=>selectedId==="new"?{...empty}:projects.find(p=>p.id===selectedId)||{...empty},[selectedId,projects]);
  const [draft,setDraft]=useState<any>(selected);
  const [busy,setBusy]=useState(false); const [status,setStatus]=useState("");
  function choose(id:string){setSelectedId(id); const p=id==="new"?{...empty}:projects.find(x=>x.id===id)||{...empty}; setDraft({...p}); setStatus("");}
  function field(name:string,value:any){setDraft((d:any)=>({...d,[name]:value,...(name==="title"&&!d.id&&!d.slug?{slug:slugify(value)}:{})}));}
  async function upload(file:File,kind:"sketch"|"hero"|"gallery",projectId:string,slug:string){const supabase=createClient(); const storagePath=`${slug}/${kind}/${Date.now()}-${safe(file.name)}`; const {error}=await supabase.storage.from("projects").upload(storagePath,file,{upsert:false,contentType:file.type||undefined}); if(error) throw error; const url=supabase.storage.from("projects").getPublicUrl(storagePath).data.publicUrl; if(kind==="gallery"){const max=Math.max(-1,...(draft.images||[]).map((i:any)=>i.position||0)); const {data,error:e}=await supabase.from("project_images").insert({project_id:projectId,image_url:url,position:max+1}).select("*").single(); if(e) throw e; setDraft((d:any)=>({...d,images:[...(d.images||[]),data]}));} else {const col=kind==="sketch"?"sketch_image":"hero_image"; const patch:any={[col]:url,updated_at:new Date().toISOString()}; if(kind==="hero"&&!draft.cover_image) patch.cover_image=url; const {error:e}=await supabase.from("projects").update(patch).eq("id",projectId); if(e) throw e; setDraft((d:any)=>({...d,...patch}));} return url;}
  async function save(){setBusy(true);setStatus("");try{const supabase=createClient(); const payload={title:draft.title,slug:draft.slug||slugify(draft.title),location:draft.location||null,area:draft.area||null,year:draft.year?Number(draft.year):null,description:draft.description||null,position:Number(draft.position)||0,featured:Boolean(draft.featured),published:Boolean(draft.published),updated_at:new Date().toISOString()}; let row:any; if(draft.id){const {data,error}=await supabase.from("projects").update(payload).eq("id",draft.id).select("*").single(); if(error) throw error; row={...draft,...data}; setProjects(ps=>ps.map(p=>p.id===row.id?row:p));}else{const {data,error}=await supabase.from("projects").insert(payload).select("*").single(); if(error) throw error; row={...data,images:[]}; setProjects(ps=>[...ps,row]); setSelectedId(row.id);} setDraft(row); setStatus("Guardado correctamente.");}catch(e:any){setStatus(`Error: ${e.message||e}`)}finally{setBusy(false)}}
  async function removeImage(image:ProjectImage){if(!confirm("¿Quitar esta imagen de la galería?"))return; const {error}=await createClient().from("project_images").delete().eq("id",image.id); if(!error)setDraft((d:any)=>({...d,images:(d.images||[]).filter((x:any)=>x.id!==image.id)}));}
  async function fileChange(e:ChangeEvent<HTMLInputElement>,kind:"sketch"|"hero"|"gallery"){if(!draft.id){alert("Primero guardá el proyecto y luego subí imágenes.");e.target.value="";return;} const files=Array.from(e.target.files||[]); if(!files.length)return; setBusy(true);try{for(const file of files)await upload(file,kind,draft.id,draft.slug);}catch(err:any){alert(err.message||err)}finally{setBusy(false);e.target.value=""}}
  return <div className="admin-project-layout"><aside className="admin-project-list"><button onClick={()=>choose("new")} className={selectedId==="new"?"active":""}>+ Nuevo proyecto</button>{projects.map(p=><button key={p.id} onClick={()=>choose(p.id)} className={selectedId===p.id?"active":""}>{p.title}<small>{p.published?"Publicado":"Borrador"}</small></button>)}</aside><section className="admin-card admin-editor"><div className="admin-editor-head"><h1>{draft.id?`Editar ${draft.title}`:"Nuevo proyecto"}</h1><button className="primary" onClick={save} disabled={busy}>{busy?"Guardando...":"Guardar"}</button></div>{status&&<p className="admin-status">{status}</p>}<div className="admin-form-grid"><label className="admin-field">Título<input value={draft.title||""} onChange={e=>field("title",e.target.value)}/></label><label className="admin-field">Slug<input value={draft.slug||""} onChange={e=>field("slug",slugify(e.target.value))}/></label><label className="admin-field">Ubicación<input value={draft.location||""} onChange={e=>field("location",e.target.value)}/></label><label className="admin-field">Superficie<input placeholder="250 m2" value={draft.area||""} onChange={e=>field("area",e.target.value)}/></label><label className="admin-field">Año<input type="number" value={draft.year||""} onChange={e=>field("year",e.target.value)}/></label><label className="admin-field">Orden<input type="number" value={draft.position||0} onChange={e=>field("position",e.target.value)}/></label><label className="admin-field admin-field-wide">Descripción<textarea value={draft.description||""} onChange={e=>field("description",e.target.value)}/></label></div><div className="admin-checks"><label><input type="checkbox" checked={!!draft.published} onChange={e=>field("published",e.target.checked)}/> Publicado</label><label><input type="checkbox" checked={!!draft.featured} onChange={e=>field("featured",e.target.checked)}/> Destacado</label><span>Likes actuales: {draft.likes_count||0}</span></div><div className="admin-media-grid"><div className="admin-upload-box"><h3>Croquis / miniatura</h3><p>Ideal: PNG/JPG 1400×1000 px, fondo blanco o transparente.</p>{draft.sketch_image&&<img src={draft.sketch_image} alt="Croquis"/>}<input type="file" accept="image/*" onChange={e=>fileChange(e,"sketch")}/></div><div className="admin-upload-box"><h3>Hero</h3><p>Ideal: 2400×1400 px o mayor, horizontal.</p>{draft.hero_image&&<img src={draft.hero_image} alt="Hero"/>}<input type="file" accept="image/*" onChange={e=>fileChange(e,"hero")}/></div></div><div className="admin-gallery"><div className="admin-gallery-head"><div><h3>Galería</h3><p>Ideal: mínimo 1600 px en el lado mayor. Se respeta el orden de carga.</p></div><input type="file" multiple accept="image/*" onChange={e=>fileChange(e,"gallery")}/></div><div className="admin-gallery-grid">{(draft.images||[]).map((img:ProjectImage)=><div key={img.id} className="admin-gallery-item"><img src={img.image_url} alt=""/><button onClick={()=>removeImage(img)}>Quitar</button></div>)}</div></div></section></div>;
}
